"""scripts/sync_lock_versions.py changes the version lines of the workspace crates and nothing else."""

import importlib.util
from pathlib import Path

import pytest

SCRIPT = (
    Path(__file__).resolve().parents[3] / "scripts" / "sync_lock_versions.py"
)
spec = importlib.util.spec_from_file_location("sync_lock_versions", SCRIPT)
sync = importlib.util.module_from_spec(spec)
spec.loader.exec_module(sync)

CARGO_LOCK = """\
# This file is automatically @generated by Cargo.
version = 4

[[package]]
name = "physure"
version = "0.2.4"
dependencies = [
 "serde",
]

[[package]]
name = "physure-cli"
version = "0.2.4"

[[package]]
name = "serde"
version = "0.2.4"
source = "registry+https://github.com/rust-lang/crates.io-index"
checksum = "abc"
"""

VERSIONS = {"physure": "0.3.0", "physure-cli": "0.3.0"}


def test_the_workspace_crates_get_the_version_of_their_manifest():
    text, changed = sync.rewrite_cargo_lock(CARGO_LOCK, VERSIONS)
    assert changed == ["physure 0.2.4 -> 0.3.0", "physure-cli 0.2.4 -> 0.3.0"]
    assert 'name = "physure"\nversion = "0.3.0"' in text
    assert 'name = "physure-cli"\nversion = "0.3.0"' in text


def test_a_registry_crate_with_the_same_number_is_not_touched():
    text, _ = sync.rewrite_cargo_lock(
        CARGO_LOCK, {"serde": "9.9.9", **VERSIONS}
    )
    assert 'name = "serde"\nversion = "0.2.4"\nsource' in text


def test_nothing_else_in_the_file_changes():
    text, _ = sync.rewrite_cargo_lock(CARGO_LOCK, VERSIONS)
    before, after = CARGO_LOCK.splitlines(), text.splitlines()
    assert len(before) == len(after)
    differing = [
        i for i, (a, b) in enumerate(zip(before, after, strict=True)) if a != b
    ]
    assert len(differing) == 2
    assert all(before[i].startswith("version = ") for i in differing)


def test_a_lock_file_that_is_up_to_date_is_left_alone():
    once, _ = sync.rewrite_cargo_lock(CARGO_LOCK, VERSIONS)
    again, changed = sync.rewrite_cargo_lock(once, VERSIONS)
    assert again == once
    assert changed == []


def test_windows_line_endings_survive():
    crlf = CARGO_LOCK.replace("\n", "\r\n")
    text, changed = sync.rewrite_cargo_lock(crlf, VERSIONS)
    assert len(changed) == 2
    assert text.count("\r\n") == crlf.count("\r\n")
    assert "\n" not in text.replace("\r\n", "")


UV_LOCK = """\
version = 1

[[package]]
name = "physure"
version = "0.2.4"
source = { editable = "." }

[[package]]
name = "other"
version = "0.2.4"
source = { registry = "https://pypi.org/simple" }
"""


def test_the_editable_physure_entry_of_uv_lock_follows_pyproject():
    text, changed = sync.rewrite_uv_lock(UV_LOCK, "0.3.0")
    assert changed == ["physure 0.2.4 -> 0.3.0"]
    assert (
        'name = "physure"\nversion = "0.3.0"\nsource = { editable = "." }'
        in text
    )
    assert 'name = "other"\nversion = "0.2.4"' in text


def test_a_physure_from_a_registry_is_not_the_project():
    registry = UV_LOCK.replace(
        'source = { editable = "." }',
        'source = { registry = "https://pypi.org/simple" }',
        1,
    )
    text, changed = sync.rewrite_uv_lock(registry, "0.3.0")
    assert changed == []
    assert text == registry


@pytest.mark.parametrize("version", ["0.2.4", "0.3.0"])
def test_the_real_lock_files_can_be_read(version):
    # the script must find the entries it is meant to rewrite in the files of this repository
    cargo, _ = sync.rewrite_cargo_lock(
        sync.CARGO_LOCK.read_text(encoding="utf-8"), {"physure": version}
    )
    uv, _ = sync.rewrite_uv_lock(
        sync.UV_LOCK.read_text(encoding="utf-8"), version
    )
    assert f'name = "physure"\nversion = "{version}"' in cargo.replace(
        "\r\n", "\n"
    )
    assert (
        f'name = "physure"\nversion = "{version}"\nsource = {{ editable = "." }}'
        in uv.replace("\r\n", "\n")
    )
